import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk3.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`104-112`,`116-124`),i=t=>({image:e(`/assets/group3/lesson-hsk3-l12-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk3-l12-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk3-l12-${t}-v1.webp`)} 1400w`}),a=(e,t)=>({...t,reading:t.pinyin,sourceRef:e}),o=(e,t,n)=>({zh:e,th:t,focus:n}),s=[[1,`街`,`jiē`,`n.`,`street`,`ถนน`,105,117],[2,`开花`,`kāihuā`,`v.`,`bloom`,`ออกดอก`,105,117],[3,`公园`,`gōngyuán`,`n.`,`park`,`สวนสาธารณะ`,105,117],[4,`船`,`chuán`,`n.`,`boat`,`เรือ`,105,117],[5,`工作日`,`gōngzuòrì`,`n.`,`weekday`,`วันทำงาน`,105,117],[6,`地方`,`dìfang`,`n.`,`place`,`สถานที่`,105,117],[7,`刚才`,`gāngcái`,`n.`,`a moment ago; just now`,`เมื่อครู่`,107,119],[8,`刮`,`guā`,`v.`,`blow (of wind)`,`พัด`,107,119],[9,`风`,`fēng`,`n.`,`wind`,`ลม`,107,119],[10,`新闻`,`xīnwén`,`n.`,`news`,`ข่าว`,107,119],[11,`伞`,`sǎn`,`n.`,`umbrella`,`ร่ม`,107,119],[12,`借`,`jiè`,`v.`,`lend; borrow`,`ให้ยืม / ยืม`,107,119],[13,`把`,`bǎ`,`m.`,`measure word for handled objects`,`ลักษณนามของสิ่งมีด้าม`,107,119],[14,`雨衣`,`yǔyī`,`n.`,`raincoat`,`เสื้อกันฝน`,107,119],[15,`变`,`biàn`,`v.`,`change`,`เปลี่ยน`,107,119],[16,`季节`,`jìjié`,`n.`,`season`,`ฤดูกาล`,107,119],[17,`变化`,`biànhuà`,`v./n.`,`change; variation`,`เปลี่ยนแปลง`,107,119],[18,`冬天`,`dōngtiān`,`n.`,`winter`,`ฤดูหนาว`,108,120],[19,`常常`,`chángcháng`,`adv.`,`often`,`บ่อย ๆ`,108,120],[20,`关注`,`guānzhù`,`v.`,`pay attention to`,`ติดตาม / ใส่ใจ`,108,120],[21,`四季`,`sìjì`,`n.`,`four seasons`,`สี่ฤดู`,110,122],[22,`春天`,`chūntiān`,`n.`,`spring`,`ฤดูใบไม้ผลิ`,110,122],[23,`夏天`,`xiàtiān`,`n.`,`summer`,`ฤดูร้อน`,110,122],[24,`凉快`,`liángkuai`,`adj.`,`cool`,`เย็นสบาย`,110,122],[25,`秋天`,`qiūtiān`,`n.`,`autumn`,`ฤดูใบไม้ร่วง`,110,122],[26,`叶子`,`yèzi`,`n.`,`leaf`,`ใบไม้`,110,122],[27,`变成`,`biànchéng`,`v.`,`become; change into`,`เปลี่ยนเป็น`,110,122]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),c=n(`105`,`117`),l=n(`107`,`119`),u=n(`108`,`120`),d={yifei:{hanzi:`王一飞`,pinyin:`Wáng Yìfēi`,nameTh:`หวังอี้เฟย`,nameEn:`Wang Yifei`,...i(`park`),imageFocus:`34% center`},bai:{hanzi:`白家月`,pinyin:`Bái Jiāyuè`,nameTh:`ไป๋เจียเยว่`,nameEn:`Bai Jiayue`,...i(`park`),imageFocus:`66% center`}},f=[{id:`h3l12-park`,number:`01`,glyph:`花`,title:`相约去公园`,titleTh:`นัดกันไปสวนสาธารณะ`,titleEn:`Planning a park visit`,place:`街上`,placeTh:`บนถนน`,...i(`park`),source:`Text 1 · หน้าเล่ม 105 · PDF หน้า 117`,sourcePage:`105`,sourceRef:c,imageAlt:{zh:`街道春景`,th:`หวังอี้เฟยกับไป๋เจียเยว่คุยเรื่องดอกไม้และสวน`,en:`Talking about flowers and visiting the park`},context:`在街上，王一飞和白家月边走边聊。`,contextTh:`บนถนน หวังอี้เฟยกับไป๋เจียเยว่เดินไปคุยไป`,contextEn:`On the street, Wang Yifei and Bai Jiayue chatted while walking.`,characters:[{role:`A`,profile:`bai`,noteZh:`想去公园坐船的人`,noteTh:`ผู้ที่อยากไปนั่งเรือในสวน`,noteEn:`The person who wants to take a boat in the park`},{role:`B`,profile:`teacherWang`,noteZh:`建议换一天的人`,noteTh:`ผู้เสนอให้เปลี่ยนวัน`,noteEn:`The person suggesting another day`}],lines:[a(c,{role:`A`,speaker:`白家月`,hanzi:`王老师，您看，这条街上的树都开花了。`,pinyin:`Wáng lǎoshī, nín kàn, zhè tiáo jiē shang de shù dōu kāihuā le.`,en:`Teacher Wang, look, all the trees on this street are blooming.`,th:`อาจารย์หวัง ดูสิ ต้นไม้บนถนนสายนี้ออกดอกหมดแล้ว`,visual:o(`树都开花了`,`ต้นไม้ออกดอกแล้ว`,`34% center`)}),a(c,{role:`B`,speaker:`王一飞`,hanzi:`上周我去公园坐船了，公园里的花也开了。`,pinyin:`Shàng zhōu wǒ qù gōngyuán zuò chuán le, gōngyuán li de huā yě kāi le.`,en:`I went boating in the park last week. The flowers there have bloomed too.`,th:`สัปดาห์ก่อนฉันไปนั่งเรือในสวน ดอกไม้ในสวนก็เบ่งบานแล้ว`,visual:o(`去公园坐船`,`ไปนั่งเรือในสวน`,`66% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`天气这么好，下午我也想去公园坐船。`,pinyin:`Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuò chuán.`,en:`The weather is so nice; I want to go boating in the park this afternoon too.`,th:`อากาศดีขนาดนี้ บ่ายนี้ฉันก็อยากไปนั่งเรือในสวน`,visual:o(`天气这么好`,`อากาศดีขนาดนี้`,`36% center`)}),a(c,{role:`B`,speaker:`王一飞`,hanzi:`去吧！今天是工作日，人应该不多。`,pinyin:`Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.`,en:`Go ahead! Today is a weekday, so there should not be many people.`,th:`ไปสิ วันนี้เป็นวันทำงาน คนน่าจะไม่มาก`,visual:o(`今天是工作日`,`วันนี้เป็นวันทำงาน`,`64% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`您有时间吗？我想跟您一起去。`,pinyin:`Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.`,en:`Do you have time? I want to go with you.`,th:`อาจารย์มีเวลาไหม? ฉันอยากไปด้วย`,visual:o(`跟您一起去`,`ไปด้วยกัน`,`38% center`)}),a(c,{role:`B`,speaker:`王一飞`,hanzi:`我今天下午有课，不能去太远的地方。`,pinyin:`Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.`,en:`I have class this afternoon and cannot go somewhere too far away.`,th:`บ่ายวันนี้ฉันมีสอน ไปที่ไกลเกินไปไม่ได้`,visual:o(`不能去太远`,`ไปไกลเกินไปไม่ได้`,`62% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`那咱们换一天去？`,pinyin:`Nà zánmen huàn yì tiān qù?`,en:`Then shall we go another day?`,th:`งั้นเราเปลี่ยนไปวันอื่นไหม?`,visual:o(`换一天去`,`เปลี่ยนไปวันอื่น`,`40% center`)}),a(c,{role:`B`,speaker:`王一飞`,hanzi:`行。或者明天去，或者后天去，我给你打电话。`,pinyin:`Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.`,en:`All right. We can go tomorrow or the day after; I will call you.`,th:`ได้ ไปพรุ่งนี้หรือวันมะรืนก็ได้ ฉันจะโทรหา`,visual:o(`或者明天，或者后天`,`พรุ่งนี้หรือวันมะรืน`,`60% center`)})],qte:{after:3,prompt:{zh:`王一飞今天为什么不能去公园？`,th:`ทำไมวันนี้หวังอี้เฟยไปสวนไม่ได้?`,en:`Why could Wang Yifei not go to the park today?`},options:[{value:`下午有课`,zh:`下午有课`,pinyin:`xiàwǔ yǒu kè`,th:`บ่ายมีสอน`},{value:`天气不好`,zh:`天气不好`,pinyin:`tiānqì bù hǎo`,th:`อากาศไม่ดี`},{value:`公园关门`,zh:`公园关门`,pinyin:`gōngyuán guānmén`,th:`สวนปิด`}],correct:`下午有课`,evidence:`王一飞：我今天下午有课。`,evidenceTh:`หวังอี้เฟย: บ่ายวันนี้ฉันมีสอน`,sourceRef:c},builder:{prompt:{zh:`重组选择复句`,th:`เรียงประโยคทางเลือก`,en:`Rebuild the alternative sentence`},answer:[`或者`,`明天去`,`或者`,`后天去`],tiles:[`后天去`,`或者`,`明天去`,`或者`],gloss:{或者:`หรือ`,明天去:`ไปพรุ่งนี้`,后天去:`ไปวันมะรืน`},translationTh:`ไปพรุ่งนี้หรือไปวันมะรืน`,translationEn:`Either go tomorrow or the day after tomorrow.`,evidence:`Text 1 · หน้าเล่ม 105`,sourceRef:c}},{id:`h3l12-rain`,number:`02`,glyph:`雨`,title:`突然刮风下雨`,titleTh:`ลมพัดและฝนตกกะทันหัน`,titleEn:`Sudden wind and rain`,place:`街上`,placeTh:`บนถนน`,...i(`rain`),source:`Text 2 · หน้าเล่ม 107 · PDF หน้า 119`,sourcePage:`107`,sourceRef:l,imageAlt:{zh:`街上躲雨场景`,th:`ทั้งสองเจอลมและฝนระหว่างเดิน`,en:`Encountering wind and rain while walking`},context:`在街上，王一飞和白家月一起散步。`,contextTh:`บนถนน ทั้งสองกำลังเดินเล่นด้วยกัน`,contextEn:`On the street, Wang Yifei and Bai Jiayue were taking a walk.`,characters:[{role:`A`,profile:`bai`,noteZh:`今天没带雨伞的人`,noteTh:`ผู้ที่วันนี้ไม่ได้พกร่ม`,noteEn:`The person without an umbrella`},{role:`B`,profile:`teacherWang`,noteZh:`愿意借雨具的人`,noteTh:`ผู้ที่ให้ยืมอุปกรณ์กันฝน`,noteEn:`The person offering rain gear`}],lines:[a(l,{role:`A`,speaker:`白家月`,hanzi:`刚才还是大晴天呢，怎么突然就刮起风来了？`,pinyin:`Gāngcái háishi dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?`,en:`It was sunny just now. Why did the wind suddenly start blowing?`,th:`เมื่อครู่ยังแดดจ้าอยู่เลย ทำไมจู่ ๆ ลมถึงพัดขึ้นมา?`,visual:o(`刮起风来了`,`ลมเริ่มพัด`,`34% center`)}),a(l,{role:`B`,speaker:`王一飞`,hanzi:`好像新闻里说今天有雨。`,pinyin:`Hǎoxiàng xīnwén li shuō jīntiān yǒu yǔ.`,en:`I think the news said it would rain today.`,th:`เหมือนในข่าวบอกว่าวันนี้มีฝน`,visual:o(`新闻说有雨`,`ข่าวบอกว่ามีฝน`,`66% center`)}),a(l,{role:`A`,speaker:`白家月`,hanzi:`啊？我每天书包里都放着雨伞，就今天没带。`,pinyin:`A? Wǒ měitiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.`,en:`What? I carry an umbrella in my bag every day, except today.`,th:`อะไรนะ? ทุกวันฉันใส่ร่มไว้ในกระเป๋า มีแค่วันนี้ที่ไม่ได้เอามา`,visual:o(`就今天没带`,`มีแค่วันนี้ที่ไม่ได้พก`,`36% center`)}),a(l,{role:`B`,speaker:`王一飞`,hanzi:`我可以借给你，我车里有一把伞和一件雨衣。`,pinyin:`Wǒ kěyǐ jiè gěi nǐ, wǒ chē li yǒu yì bǎ sǎn hé yí jiàn yǔyī.`,en:`I can lend you one. I have an umbrella and a raincoat in my car.`,th:`ฉันให้ยืมได้ ในรถมีร่มหนึ่งคันกับเสื้อกันฝนหนึ่งตัว`,visual:o(`借给你一把伞`,`ให้ยืมร่มหนึ่งคัน`,`64% center`)}),a(l,{role:`A`,speaker:`白家月`,hanzi:`谢谢，希望下午天气能变好。`,pinyin:`Xièxie, xīwàng xiàwǔ tiānqì néng biàn hǎo.`,en:`Thank you. I hope the weather improves this afternoon.`,th:`ขอบคุณ หวังว่าบ่ายนี้อากาศจะดีขึ้น`,visual:o(`天气能变好`,`อากาศดีขึ้น`,`38% center`)}),a(l,{role:`B`,speaker:`王一飞`,hanzi:`这个季节天气变化很快。`,pinyin:`Zhège jìjié tiānqì biànhuà hěn kuài.`,en:`The weather changes quickly in this season.`,th:`ฤดูนี้อากาศเปลี่ยนเร็วมาก`,visual:o(`天气变化很快`,`อากาศเปลี่ยนเร็ว`,`62% center`)}),a(l,{role:`A`,speaker:`白家月`,hanzi:`雨已经下起来了，咱们快点儿走吧。`,pinyin:`Yǔ yǐjīng xià qǐlai le, zánmen kuài diǎnr zǒu ba.`,en:`It has started raining. Let us walk faster.`,th:`ฝนเริ่มตกแล้ว เรารีบเดินกันเถอะ`,visual:o(`雨下起来了`,`ฝนเริ่มตกแล้ว`,`40% center`)})],qte:{after:3,prompt:{zh:`王一飞车里有什么？`,th:`ในรถของหวังอี้เฟยมีอะไร?`,en:`What did Wang Yifei have in the car?`},options:[{value:`伞和雨衣`,zh:`伞和雨衣`,pinyin:`sǎn hé yǔyī`,th:`ร่มและเสื้อกันฝน`},{value:`两把伞`,zh:`两把伞`,pinyin:`liǎng bǎ sǎn`,th:`ร่มสองคัน`},{value:`雨鞋`,zh:`雨鞋`,pinyin:`yǔxié`,th:`รองเท้ากันฝน`}],correct:`伞和雨衣`,evidence:`王一飞：我车里有一把伞和一件雨衣。`,evidenceTh:`หวังอี้เฟย: ในรถฉันมีร่มหนึ่งคันกับเสื้อกันฝนหนึ่งตัว`,sourceRef:l},builder:{prompt:{zh:`重组趋向补语句`,th:`เรียงประโยคส่วนเสริมทิศทาง`,en:`Rebuild the directional-complement sentence`},answer:[`雨`,`已经`,`下起来了`],tiles:[`下起来了`,`雨`,`已经`],gloss:{雨:`ฝน`,已经:`แล้ว`,下起来了:`เริ่มตกขึ้นมา`},translationTh:`ฝนเริ่มตกแล้ว`,translationEn:`It has started raining.`,evidence:`Text 2 · หน้าเล่ม 107`,sourceRef:l}},{id:`h3l12-winter`,number:`03`,glyph:`冬`,title:`谈冬天和下雪`,titleTh:`คุยเรื่องฤดูหนาวและหิมะ`,titleEn:`Talking about winter and snow`,place:`教室`,placePy:`jiàoshì`,placeTh:`ห้องเรียน`,...i(`winter`),source:`Text 3 · หน้าเล่ม 108 · PDF หน้า 120`,sourcePage:`108`,sourceRef:u,imageAlt:{zh:`教室谈天气场景`,th:`คุยเรื่องการปรับตัวกับฤดูหนาว`,en:`Discussing winter weather in a classroom`},context:`在教室里，王一飞和白家月躲雨。`,contextTh:`ในห้องเรียน ทั้งสองหลบฝนและคุยเรื่องอากาศ`,contextEn:`In the classroom, they sheltered from the rain and discussed the weather.`,characters:[{role:`A`,profile:`bai`,noteZh:`喜欢下雪景色的人`,noteTh:`ผู้ที่ชอบทิวทัศน์ยามหิมะตก`,noteEn:`The person who likes snowy scenery`},{role:`B`,profile:`teacherWang`,noteZh:`还不习惯冬天的人`,noteTh:`ผู้ที่ยังไม่ชินกับฤดูหนาว`,noteEn:`The person not yet used to winter`}],lines:[a(u,{role:`A`,speaker:`白家月`,hanzi:`您来这里已经一年多了，习惯了吧？`,pinyin:`Nín lái zhèli yǐjīng yì nián duō le, xíguàn le ba?`,en:`You have been here more than a year. You must be used to it now?`,th:`อาจารย์มาอยู่ที่นี่กว่าหนึ่งปีแล้ว คงชินแล้วใช่ไหม?`,visual:o(`已经一年多了`,`กว่าหนึ่งปีแล้ว`,`34% center`)}),a(u,{role:`B`,speaker:`王一飞`,hanzi:`别的早就习惯了，就是天气我还不太习惯。`,pinyin:`Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.`,en:`I got used to everything else long ago; it is just the weather I am not used to.`,th:`อย่างอื่นชินนานแล้ว มีแค่อากาศที่ฉันยังไม่ค่อยชิน`,visual:o(`天气还不太习惯`,`ยังไม่ค่อยชินอากาศ`,`66% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`为什么？您不喜欢这里的天气吗？`,pinyin:`Wèishénme? Nín bù xǐhuan zhèli de tiānqì ma?`,en:`Why? Do you not like the weather here?`,th:`ทำไม? อาจารย์ไม่ชอบอากาศที่นี่หรือ?`,visual:o(`为什么`,`ทำไม`,`36% center`)}),a(u,{role:`B`,speaker:`王一飞`,hanzi:`我觉得冬天太冷了。`,pinyin:`Wǒ juéde dōngtiān tài lěng le.`,en:`I think winter is too cold.`,th:`ฉันคิดว่าฤดูหนาวหนาวเกินไป`,visual:o(`冬天太冷了`,`ฤดูหนาวหนาวเกินไป`,`64% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`冬天虽然冷，但是下雪的时候特别漂亮。`,pinyin:`Dōngtiān suīrán lěng, dànshì xià xuě de shíhou tèbié piàoliang.`,en:`Although winter is cold, it is especially beautiful when it snows.`,th:`แม้ฤดูหนาวจะหนาว แต่ตอนหิมะตกสวยเป็นพิเศษ`,visual:o(`下雪时特别漂亮`,`ตอนหิมะตกสวยมาก`,`38% center`)}),a(u,{role:`B`,speaker:`王一飞`,hanzi:`我也喜欢雪。北京常常下雪，但听说今年就下了一次。`,pinyin:`Wǒ yě xǐhuan xuě. Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xià le yí cì.`,en:`I like snow too. It often snows in Beijing, but I heard it has snowed only once this year.`,th:`ฉันก็ชอบหิมะ ปักกิ่งหิมะตกบ่อย แต่ได้ยินว่าปีนี้ตกแค่ครั้งเดียว`,visual:o(`今年就下了一次`,`ปีนี้ตกแค่ครั้งเดียว`,`62% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。`,pinyin:`Wǒ méi guānzhùguo Běijīng de tiānqì, dànshì xīnwén li shuōguo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.`,en:`I have not followed Beijing's weather, but the news said many places have had less snow this winter.`,th:`ฉันไม่ได้ติดตามอากาศปักกิ่ง แต่ข่าวบอกว่าฤดูหนาวปีนี้หลายที่หิมะตกน้อยลง`,visual:o(`很多地方雪少了`,`หลายที่หิมะน้อยลง`,`40% center`)})],qte:{after:4,prompt:{zh:`王一飞还不习惯什么？`,th:`หวังอี้เฟยยังไม่ชินกับอะไร?`,en:`What was Wang Yifei still not used to?`},options:[{value:`这里的天气`,zh:`这里的天气`,pinyin:`zhèli de tiānqì`,th:`อากาศที่นี่`},{value:`这里的饭菜`,zh:`这里的饭菜`,pinyin:`zhèli de fàncài`,th:`อาหารที่นี่`},{value:`学校的课程`,zh:`学校的课程`,pinyin:`xuéxiào de kèchéng`,th:`วิชาที่โรงเรียน`}],correct:`这里的天气`,evidence:`王一飞：就是天气我还不太习惯。`,evidenceTh:`หวังอี้เฟย: มีแค่อากาศที่ฉันยังไม่ค่อยชิน`,sourceRef:u},builder:{prompt:{zh:`重组“就”字句`,th:`เรียงประโยคที่ใช้ 就`,en:`Rebuild the 就 sentence`},answer:[`听说`,`今年`,`就下了`,`一次`],tiles:[`一次`,`听说`,`就下了`,`今年`],gloss:{听说:`ได้ยินว่า`,今年:`ปีนี้`,就下了:`ตกเพียง`,一次:`หนึ่งครั้ง`},translationTh:`ได้ยินว่าปีนี้ตกแค่ครั้งเดียว`,translationEn:`I heard it has snowed only once this year.`,evidence:`Text 3 · หน้าเล่ม 108`,sourceRef:u}}],p={id:`hsk3-l12`,slug:`lesson-12`,level:`hsk3`,number:12,featured:!1,sourceRef:r,source:{title:`新HSK教程 3 · New HSK Course 3`,lesson:`Lesson 12 · 这个季节天气变化很快`,printedPages:`104–112`,pdfPages:`116–124`,file:`hsk3.pdf`,sourceRef:r},title:{zh:`这个季节天气变化很快`,pinyin:`Zhège jìjié tiānqì biànhuà hěn kuài`,en:`The weather changes rapidly in this season`,thAid:`ฤดูนี้อากาศเปลี่ยนแปลงเร็วมาก`},summary:{zh:`谈天气变化、四季特点和季节偏好。`,en:`Discuss weather changes, the four seasons, and seasonal preferences.`,thAid:`พูดคุยเรื่องอากาศเปลี่ยนแปลง ลักษณะสี่ฤดู และฤดูที่ชอบ`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并谈论天气变化。`,en:`Be able to understand and talk about weather changes.`,thAid:`ฟังเข้าใจและพูดคุยเกี่ยวกับการเปลี่ยนแปลงของอากาศ`,sourceRef:n(`104`,`116`)},{zh:`能听懂并介绍某地的气候情况及自己对季节的喜好。`,en:`Be able to understand and describe the climate of a place and express personal preferences for seasons.`,thAid:`ฟังเข้าใจและแนะนำภูมิอากาศของสถานที่หนึ่ง รวมทั้งบอกฤดูที่ตนชอบ`,sourceRef:n(`104`,`116`)},{zh:`掌握“就”的用法，能强调数量少或例外情况。`,en:`Master 就 to emphasize small quantities or exceptions.`,thAid:`ใช้ 就 เพื่อเน้นว่ามีจำนวนน้อยหรือเป็นกรณียกเว้น`,sourceRef:n(`104`,`116`)},{zh:`了解北京的四季特点。`,en:`Understand the characteristics of the four seasons in Beijing.`,thAid:`เรียนรู้ลักษณะเด่นของทั้งสี่ฤดูในปักกิ่ง`,sourceRef:n(`104`,`116`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`104`,route:`/home/hsk3/lesson-12/preface/`,sourceRef:n(`104`,`116`)},{number:`01`,title:`相约去公园`,titleTh:`นัดกันไปสวน`,detail:`Text 1 · New Words 1–6`,pages:`105–106`,scene:1,sourceRef:n(`105-106`,`117-118`)},{number:`02`,title:`突然刮风下雨`,titleTh:`ลมพัดและฝนตกกะทันหัน`,detail:`Text 2 · New Words 7–17`,pages:`106–107`,scene:2,sourceRef:n(`106-107`,`118-119`)},{number:`03`,title:`谈冬天和下雪`,titleTh:`คุยเรื่องฤดูหนาวและหิมะ`,detail:`Text 3 · New Words 18–20`,pages:`108–109`,scene:3,sourceRef:n(`108-109`,`120-121`)},{number:`04`,title:`北京四季、练习与活动`,titleTh:`สี่ฤดูปักกิ่ง แบบฝึก และกิจกรรม`,detail:`Text 4 · Exercises · Activity`,pages:`109–112`,sourceRef:n(`109-112`,`121-124`)}],vocabulary:s,grammarFocus:[{title:`选择复句“或者……，或者……”`,titleEn:`Alternative complex sentence`,explanationZh:`表示在两个或多个可能选项中选择一个，多用于口语。`,explanationEn:`This pattern presents a choice among two or more possibilities, commonly in speech.`,thAid:`ใช้เสนอให้เลือกหนึ่งอย่างจากสองทางเลือกขึ้นไป มักใช้ในภาษาพูด`,examples:[`或者明天去，或者后天去。`,`或者今天看，或者明天看。`],sourceRef:n(`106`,`118`)},{title:`趋向补语“起来”`,titleEn:`Directional complement 起来`,explanationZh:`放在动词或形容词后，表示动作开始或进入新状态。`,explanationEn:`起来 after a verb or adjective marks the start of an action or a new state.`,thAid:`起来 ตามหลังกริยาหรือคำคุณศัพท์เพื่อบอกการเริ่มกระทำหรือเข้าสู่สภาพใหม่`,examples:[`雨已经下起来了。`,`最近天气热起来了。`,`怎么突然刮起风来了？`],sourceRef:n(`107-108`,`119-120`)},{title:`范围副词“就”`,titleEn:`Adverb of scope 就`,explanationZh:`“就”可强调数量少、程度轻、时间短，也可表示例外情况。`,explanationEn:`就 can emphasize a small quantity, low degree, short duration, or an exception.`,thAid:`就 ใช้เน้นว่าจำนวนน้อย ระดับเบา เวลาสั้น หรือเป็นข้อยกเว้น`,examples:[`今年就下了一次雪。`,`就今天没带雨伞。`],sourceRef:n(`109`,`121`)}],characters:d,scenes:f};export{p as LESSON_HSK3_L12};